'use strict';

// ─── avatar.js ──────────────────────────────────────────────────────────────
// Shared merchant avatar. Loaded globally (pages/partials/scripts.html) so
// every consumer — transactions.js, recurring.js — renders the SAME merchant
// the SAME way everywhere in the app.
//
// Two tiers, precision-first like everything else that guesses at a merchant:
//   1. A BUNDLED BRAND ICON, when the label names a merchant we shipped one
//      for (merchant-icons.js, generated by electron/scripts/fetch-merchant-
//      icons.js). Exact slug match only — see merchantIconSlug.
//   2. Otherwise the original deterministic colour + initials circle, hashed
//      from the label, which needs no lookup table to stay stable.
//
// Icons are ORDINARY BUNDLED ASSETS under static/merchant-icons/, downloaded
// once on a developer's machine and committed. The app still makes no network
// call and still works with no internet (see PRODUCT.md); nothing here fetches
// a logo at runtime, and a missing file degrades to tier 2 rather than showing
// a broken image. CSS for both tiers lives in ui.css.
//
// Extracted from transactions.js, which originated this algorithm for the
// ledger's row icon.

(function () {
    // Fast, deterministic string hash (djb2) — no cryptographic properties
    // needed, just a stable, well-distributed bucket per merchant name.
    function avatarHashString(str) {
        let h = 5381;
        for (let i = 0; i < str.length; i++) {
            h = ((h << 5) + h) + str.charCodeAt(i);
            h |= 0;
        }
        return Math.abs(h);
    }

    // First letters of the first two words, or the first two characters of a
    // single word. Leading punctuation is stripped per word first — raw bank
    // strings the lexicon didn't clean up often start a word with '*' or '#'
    // (POS prefixes like "SQ *MERCHANT"), which would otherwise become the
    // initial itself. '?' covers the no-description edge case (never hashed
    // to a colour — see merchantAvatarHtml).
    function avatarInitials(name) {
        const words = String(name || '').trim().split(/\s+/)
            .map(w => w.replace(/^[^a-zA-Z0-9]+/, ''))
            .filter(Boolean);
        if (words.length === 0) return '?';
        if (words.length === 1) return words[0].slice(0, 2).toUpperCase();
        return (words[0][0] + words[1][0]).toUpperCase();
    }

    // Trimmed copy of the noise patterns the backend categorizer strips before
    // matching (electron/backend/services/merchantCategories.js NOISE_PATTERNS)
    // — this file can't require() that Node module (the renderer runs with
    // nodeIntegration off), and colour-grouping only needs the *row-varying*
    // noise gone, not lexicon-grade precision, so this is a deliberately
    // smaller subset: payment-processor '*' prefixes, card masks, and
    // store/phone/trace/confirmation numbers. Without this, two deposits from
    // the same payroll processor ("DIRECT DEP ACME CORP ID:41355400" vs
    // "...ID:64140689") hashed as different merchants purely because their
    // trailing reference number differs — the same bug class the categorizer
    // solves for matching, just for colour instead of a category.
    const AVATAR_NOISE = [
        /\b(sq|tst|sp|pp|paypal|google|goog|apl|apple|toast|clover|venmo|cash app|zelle)\s*\*+\s*/gi,
        /[x*]{2,}\d+/gi,
        /\*+/g,
        /#\s*\d+/g,
        /\b\d{3}[-.\s]?\d{3}[-.\s]?\d{4}\b/g, // phone numbers
        /\b\d{1,2}\/\d{1,2}(?:\/\d{2,4})?\b/g, // embedded dates
        /\b\d{3,}\b/g, // standalone id/auth/store-number runs
    ];

    function avatarColorKey(label) {
        let s = String(label || '').toLowerCase();
        for (const re of AVATAR_NOISE) s = s.replace(re, ' ');
        return s.replace(/\s+/g, ' ').trim();
    }

    // 8 fixed slots (.avatar-circle-0..7 in ui.css) — light/desaturated steps
    // of the same 8 hues as the dataviz skill's categorical palette, evenly
    // spaced by hue angle for pastel distinguishability (see ui.css for why).
    // The colour hash runs on the noise-stripped key (above) so unrecognized
    // merchants with a varying trailing reference number still land on one
    // colour; initials stay on the original label — the first-two-words
    // heuristic rarely touches that trailing noise anyway, and it's what's
    // actually printed alongside it.
    const AVATAR_SLOTS = 8;

    // ── Brand icons ─────────────────────────────────────────────────────────
    // The join between a label on screen and a file on disk. Deliberately NOT
    // the noise-stripped colour key: that key is built to be lossy (it groups
    // "ACME CORP ID:41355400" with "ACME CORP ID:64140689"), and lossy is the
    // wrong instinct when the output is a brand's logo. This is an exact match
    // on alphanumerics — either the label is the merchant's name or it isn't.
    //
    // In practice the label is already a curated display name for the rows that
    // can match: the import pipeline writes transactions.display_name only from
    // the merchant lexicon's dictionary (see the clean-display-name rule), and
    // that same lexicon is what generated the icon set. A raw bank description
    // that was never recognized ("SQ *BLUE BOTTLE 866-123 CA") slugs to
    // something no brand claims and falls through to the initials circle, which
    // is exactly the abstention we want. Must stay identical to slugify() in
    // electron/scripts/fetch-merchant-icons.js.
    function merchantIconSlug(label) {
        return String(label || '')
            .toLowerCase()
            .replace(/&/g, 'and')
            .replace(/[^a-z0-9]+/g, '');
    }

    function merchantIconFile(label) {
        const map = window.MERCHANT_ICONS;
        if (!map) return null; // manifest not generated / not loaded
        const slug = merchantIconSlug(label);
        return (slug && Object.prototype.hasOwnProperty.call(map, slug)) ? map[slug] : null;
    }

    // Icons whose artwork reaches all four corners (a brand-colour tile, not a
    // mark on transparency) fill the circle and get clipped round — they ARE
    // the disc. Everything else sits inset on a neutral one, or a dark monogram
    // drawn for a browser tab would have nothing to stand on. The measurement
    // happens at build time from the actual pixels (see merchant-icons.js);
    // the browser can't ask an <img> whether its corners are transparent.
    // Built lazily so a page that renders no avatar pays nothing.
    let bleedSet = null;
    function isFullBleed(file) {
        if (bleedSet === null) bleedSet = new Set(window.MERCHANT_ICONS_BLEED || []);
        return bleedSet.has(file);
    }

    /** The merchant avatar for `label`: a bundled brand icon when we have one,
     *  otherwise the deterministic colour + initials circle. `label` is expected
     *  pre-escaped-safe (callers pass it through escapeHtml themselves, matching
     *  how every other renderer in this app builds HTML strings). */
    function merchantAvatarHtml(label) {
        const initials = avatarInitials(label);
        const colorKey = avatarColorKey(label);
        const slot = colorKey ? avatarHashString(colorKey) % AVATAR_SLOTS : 0;

        const file = merchantIconFile(label);
        if (file) {
            const fit = isFullBleed(file) ? ' avatar-circle-bleed' : '';
            // The initials circle this icon replaced is carried along on the
            // element, so the error path below can restore the real fallback
            // instead of an empty disc. Computing it here costs nothing and is
            // the only place the label is still in hand.
            return `<span class="avatar-circle avatar-circle-icon${fit}" aria-hidden="true"` +
                ` data-fallback="${escapeHtml(initials)}" data-slot="${slot}">` +
                `<img src="/static/merchant-icons/${encodeURIComponent(file)}.png" alt="" loading="lazy"></span>`;
        }
        return `<span class="avatar-circle avatar-circle-${slot}" aria-hidden="true">${escapeHtml(initials)}</span>`;
    }

    // A brand icon that fails to load (file pruned, asset dir missing from a
    // package) would otherwise leave a broken-image glyph in the ledger. Swap
    // it for the initials circle it would have been — same size, same colour it
    // would have hashed to, so the row is indistinguishable from one whose
    // merchant we never had an icon for. Capture-phase, because <img> error
    // events do not bubble; one listener on the document covers every avatar
    // any page renders, including the ones drawn later.
    document.addEventListener('error', (ev) => {
        const img = ev.target;
        const box = img && img.tagName === 'IMG' ? img.parentElement : null;
        if (!box || !box.classList.contains('avatar-circle-icon')) return;
        box.classList.remove('avatar-circle-icon', 'avatar-circle-bleed');
        box.classList.add(`avatar-circle-${box.dataset.slot || 0}`);
        box.textContent = box.dataset.fallback || '?';
    }, true);

    window.merchantAvatarHtml = merchantAvatarHtml;
    window.merchantIconSlug = merchantIconSlug;
}());
